global$checks,$wpdb;$checks=[];$users=[];$posts=[];$orders=[];$mails=0;$network=0;$prefix='strc_pr2829_qa_'.bin2hex(random_bytes(5));
function p29_check(bool$ok,string$name):void{global$checks;if(!$ok)throw new RuntimeException($name);$checks[]=$name;}
function p29_call(object|string$o,string$m,...$args):mixed{return(new ReflectionMethod($o,$m))->invoke(is_string($o)?null:$o,...$args);}
function p29_user(int$id):void{wp_set_current_user(0);wp_set_current_user($id);}
function p29_capture(callable$f):array{ob_start();try{$v=$f();ob_end_clean();return['value'=>$v];}catch(RuntimeException$e){$body=ob_get_clean();if($e->getMessage()==='P29 stop')return json_decode($body,true)?:['denied'=>true];throw$e;}}
add_filter('wp_die_ajax_handler',static fn()=>static function(){throw new RuntimeException('P29 stop');});add_filter('wp_die_handler',static fn()=>static function(){throw new RuntimeException('P29 stop');});
add_filter('pre_wp_mail',static function()use(&$mails){$mails++;return true;});add_filter('pre_http_request',static function()use(&$network){$network++;return new WP_Error('qa','External requests blocked');});
foreach(['strc_ad','strc_album','strc_document','strc_topic','strc_event']as$type)if(!post_type_exists($type))register_post_type($type,['public'=>false]);
try{
 foreach(['member'=>['strc_member'],'other'=>['strc_member'],'staff'=>['strc_member','strc_marketplace_moderator','strc_gallery_moderator','strc_shop_manager'],'finance'=>['strc_member','strc_treasurer']]as$key=>$roles){$id=wp_insert_user(['user_login'=>$prefix.'_'.$key,'user_pass'=>wp_generate_password(40,true,true),'user_email'=>$prefix.'_'.$key.'@example.invalid','first_name'=>'QA','last_name'=>$key,'role'=>'']);if(is_wp_error($id))throw new RuntimeException('Fixture creation');$users[$key]=(int)$id;foreach($roles as$role)(new WP_User($id))->add_role($role);(new MembershipRepository())->syncUser($id);update_user_meta($id,'strc_phone','+41790000000');update_user_meta($id,'strc_city','Bern');}
 foreach(['add_user_metadata','update_user_metadata','delete_user_metadata']as$hook)add_filter($hook,static fn($v,$id)=>in_array((int)$id,$users,true)?$v:true,10,2);
 p29_user($users['member']);$session=new MemberSessionEndpoint(new MembershipRepository());$a=p29_capture(fn()=>$session->respond());p29_check($a['contact']['email']===get_userdata($users['member'])->user_email&&$a['contact']['city']==='Bern','Session exposes own contact prefill');p29_user($users['other']);$b=p29_capture(fn()=>$session->respond());p29_check($b['contact']['email']!==$a['contact']['email'],'Session never reuses another member contact');p29_user(0);$guest=p29_capture(fn()=>$session->respond());p29_check(empty($guest['contact'])&&!$guest['memberAccess'],'Guests receive no member contact');
 $args=apply_filters('woocommerce_form_field_args',['required'=>false,'label'=>'Telefon (optional)'],'billing_phone');p29_check($args['required']&&$args['label']==='Mobilnummer (für Rückfragen)','Rendered phone field overrides optional setting');$html=woocommerce_form_field('billing_phone',['type'=>'tel','required'=>false,'label'=>'Telefon','return'=>true],'');p29_check(!str_contains($html,'(optional)')&&str_contains($html,'Mobilnummer'),'Phone markup shows required mobile label');$e=new WP_Error();do_action('woocommerce_after_checkout_validation',['billing_phone'=>' '],$e);p29_check((bool)$e->get_error_message('billing_phone_required'),'Empty phone rejected server-side');do_action('woocommerce_after_checkout_validation',['billing_phone'=>''],$e);p29_check(count($e->get_error_messages('billing_phone_required'))===1,'Phone error not duplicated');$e=new WP_Error();do_action('woocommerce_after_checkout_validation',['billing_phone'=>'+41790000000'],$e);p29_check(!$e->has_errors(),'Present phone passes additional validation');add_filter('locale',static fn()=>'fr_FR');$fr=apply_filters('woocommerce_form_field_args',['required'=>false],'billing_phone');p29_check($fr['required']&&$fr['label']==='Mobile (pour les questions)','French phone label required');remove_all_filters('locale');
 foreach([['',false],[[''],false],[[[]],false],[[['model'=>'','component'=>'','area'=>'']],false],[[['model'=>'TR6']],true],[[['model'=>'TR4']],false],[[['component'=>'Motor']],true]]as[$rows,$expected]){p29_check(p29_call(ForumSettings::class,'matches',(array)$rows,['model'=>'TR6','component'=>'Motor','area'=>'Technik'],false)===$expected,'Expert match '.count($checks));}p29_check(p29_call(ForumSettings::class,'matches',[[]],['model'=>'TR6'],true),'Explicit wildcard interest still matches');
 p29_user($users['staff']);$community=new CommunityEndpoint();$base=['kind'=>'gallery','title'=>'QA album','description'=>str_repeat('a',250)];p29_check(p29_call($community,'texts',$base)[1]===str_repeat('a',250),'New 250-character album text accepted');$fail=p29_capture(fn()=>p29_call($community,'texts',array_merge($base,['description'=>str_repeat('a',251)])));p29_check(($fail['success']??true)===false,'Long new album description rejected');$long=str_repeat('b',400);$album=wp_insert_post(['post_type'=>'strc_album','post_status'=>'publish','post_author'=>$users['member'],'post_title'=>'QA legacy album','post_content'=>$long]);$posts[]=$album;p29_check(p29_call($community,'texts',['operation'=>'edit','id'=>(string)$album,'title'=>'QA title change','description'=>$long])[1]===$long,'Unchanged long legacy description retained without kind input');$fail=p29_capture(fn()=>p29_call($community,'texts',['operation'=>'edit','id'=>(string)$album,'title'=>'QA','description'=>str_repeat('c',300)]));p29_check(($fail['success']??true)===false,'Changed oversized legacy description rejected');
 $market=new MarketplaceEndpoint();$ad=wp_insert_post(['post_type'=>'strc_ad','post_status'=>'publish','post_author'=>$users['member'],'post_title'=>'QA ad','post_content'=>'QA']);$posts[]=$ad;update_post_meta($ad,'strc_ad_public_approved','1');$input=['id'=>(string)$ad,'title'=>'QA corrected','description'=>'QA corrected text','price'=>'100','category'=>'Fahrzeuge','model'=>'TR6','year'=>'1972','condition'=>'Fahrbereit','location'=>'Bern'];$_FILES=[];$edited=p29_call($market,'changeAd','edit',$input);p29_check(!is_wp_error($edited)&&get_post_status($ad)==='publish','Moderator edit keeps other member ad published');p29_check(!empty(get_post_meta($ad,'strc_review',true)['edited'])&&get_post_meta($ad,'strc_ad_public_approved',true)==='1','Moderator edit preserves public approval and audit');p29_user($users['other']);p29_check(is_wp_error(p29_call($market,'deleteAd',['id'=>(string)$ad])),'Ordinary member cannot trash others ad');p29_user($users['staff']);$gone=p29_call($market,'deleteAd',['id'=>(string)$ad]);p29_check(!is_wp_error($gone)&&get_post_status($ad)==='trash','Marketplace moderation uses recoverable trash');wp_untrash_post($ad);p29_check(get_post_status($ad)!=='trash'&&get_post($ad)->post_content==='QA corrected text','Trashed ad content can be restored');
 // Filter only report queries to fixtures; real orders are never read by assertions or modified.
 $fixtureMode=false;add_filter('woocommerce_order_query_args',static function($args)use(&$orders,&$fixtureMode){if($fixtureMode)$args['include']=array_values($orders)?:[0];return$args;});
 foreach(['on-hold'=>10,'processing'=>20,'completed'=>30,'pending'=>40,'cancelled'=>50,'refunded'=>60,'failed'=>70]as$status=>$amount){$o=wc_create_order(['customer_id'=>$users['member'],'status'=>'pending']);$orders[]=$o->get_id();$o->set_currency('CHF');$o->set_total($amount);$o->set_payment_method('bacs');$o->set_payment_method_title('Rechnung');$o->set_status($status);$o->save();}$fixtureMode=true;$shop=new ShopEndpoint();p29_user($users['member']);$denied=p29_capture(fn()=>p29_call($shop,'reports',['summary'=>'1']));p29_check(($denied['success']??true)===false,'Member cannot read shop reports');p29_user($users['staff']);$report=p29_capture(fn()=>p29_call($shop,'reports',['summary'=>'1']));$sum=$report['data']['summary']??[];p29_check(($sum['count']??0)===4&&(float)($sum['total']??0)===100.0,'Summary excludes cancelled refunded failed orders');p29_check((float)$sum['paid']===50.0&&(float)$sum['open']===50.0,'Summary separates paid from open invoice totals');p29_check(count($sum['byStatus'])===4&&$sum['byMethod'][0]['label']==='Rechnung','Summary groups actual statuses and payment method');p29_user($users['finance']);$report=p29_capture(fn()=>p29_call($shop,'reports',['summary'=>'1']));p29_check(($report['data']['summary']['count']??0)===4,'Treasurer can inspect summary');$fixtureMode=false;
 echo wp_json_encode(['passed'=>count($checks),'checks'=>$checks,'interceptedMails'=>$mails,'externalRequests'=>$network]);
}finally{foreach($orders as$id){$o=wc_get_order($id);if($o)$o->delete(true);}foreach($posts as$id)wp_delete_post($id,true);require_once ABSPATH.'wp-admin/includes/user.php';foreach($users as$id){$wpdb->delete($wpdb->prefix.'strc_memberships',['user_id'=>$id]);wp_delete_user($id);}}
